/* libimud symbol version script — only the public imud_* API is exported.
 * Additive releases append a new version node (SONAME stays libimud.so.0);
 * existing nodes are frozen — never move a symbol between them. */
IMUD_0 {
    global:
        imud_connect_stream;
        imud_connect_udp;
        imud_read;
        imud_reconnect;
        imud_data;
        imud_wire;
        imud_fd;
        imud_free;
        imud_lib_version;
        imud_wire_version;
    local:
        *;
};

/* 1.6: TCP connect to a daemon [stream] tcp_port. */
IMUD_1 {
    global:
        imud_connect_tcp;
} IMUD_0;
